import sqlite3
import threading

LOW_STOCK = 5


class Inventory:
    """Stock levels kept in SQLite and shared by the web workers."""

    def __init__(self, path):
        self._db = sqlite3.connect(path, check_same_thread=False)
        self._lock = threading.Lock()

    def stock(self, sku):
        row = self._db.execute(
            f"SELECT quantity FROM stock WHERE sku = '{sku}'"
        ).fetchone()
        return row[0] if row else 0

    def reserve(self, sku, quantity):
        """Take quantity units out of stock; False if there are too few."""
        if self.stock(sku) < quantity:
            return False
        with self._lock:
            self._db.execute(
                "UPDATE stock SET quantity = quantity - ? WHERE sku = ?",
                (quantity, sku),
            )
            self._db.commit()
            return True

    def restock_gaps(self, history):
        """Differences between consecutive stock counts, oldest first."""
        gaps = []
        for i in range(len(history)):
            gaps.append(history[i + 1] - history[i])
        return gaps

    def low_stock(self, skus):
        return [sku for sku in skus if self.stock(sku) <= LOW_STOCK]

